  1	//! The one contract for interactive prompts: where they may run, how they end, and how `$EDITOR` is used.
  2	
  3	use std::io::IsTerminal as _;
  4	
  5	use inquire::validator::Validation;
  6	use inquire::Text;
  7	
  8	use crate::cli::OutputFormat;
  9	use crate::error::CliError;
 10	
 11	/// Proof that this run may prompt; only [`Prompts::detect`] makes one.
 12	pub struct Prompts(());
 13	
 14	impl Prompts {
 15	    /// Prompts need a person at the terminal (stdin, and stderr where they draw) and a text run: `--format json` is for
 16	    /// scripts and never prompts.
 17	    pub fn detect(format: OutputFormat) -> Option<Self> {
 18	        (format == OutputFormat::Text && std::io::stdin().is_terminal() && std::io::stderr().is_terminal())
 19	            .then_some(Self(()))
 20	    }
 21	
 22	    #[cfg(test)]
 23	    pub fn for_tests() -> Self {
 24	        Self(())
 25	    }
 26	}
 27	
 28	/// Printed whenever a prompt run ends without writing.
 29	pub const CANCELLED: &str = "Cancelled, nothing written.";
 30	
 31	/// Exit status for a prompt cancelled with Esc or Ctrl-C: 130, as shells report SIGINT.
 32	pub const CANCELLED_EXIT: u8 = 130;
 33	
 34	/// Asks which of `names` to pick, as `git add -i` does: the list is printed once, numbered, with `marked` ones starred,
 35	/// then one typed line answers. Nothing is redrawn, so no terminal size or resize can misdraw it. Enter keeps the marked
 36	/// ones; an answer that names nothing listed is asked again with the reason.
 37	pub(crate) fn pick_many(heading: &str, names: &[String], marked: &[bool]) -> Result<Vec<usize>, CliError> {
 38	    print_list(heading, names, marked);
 39	    let enter = if marked.contains(&true) {
 40	        "Enter keeps the * ones"
 41	    } else {
 42	        "Enter picks none"
 43	    };
 44	    eprintln!("{enter}, or type numbers, ranges (1-3) or names; Esc cancels.");
 45	    read_answer(names, marked, false)
 46	}
 47	
 48	/// Asks for exactly one of `names`, the way [`pick_many`] asks for several.
 49	pub(crate) fn pick_one(heading: &str, names: &[String]) -> Result<usize, CliError> {
 50	    print_list(heading, names, &[]);
 51	    eprintln!("Type a number or a name; Esc cancels.");
 52	    let picked = read_answer(names, &[], true)?;
 53	    Ok(*picked
 54	        .first()
 55	        .expect("the validator accepts only an answer naming exactly one entry"))
 56	}
 57	
 58	fn print_list(heading: &str, names: &[String], marked: &[bool]) {
 59	    let width = names.len().to_string().len();
 60	    let mut text = format!("{heading}\n");
 61	    for (index, name) in names.iter().enumerate() {
 62	        let mark = if marked.get(index) == Some(&true) { '*' } else { ' ' };
 63	        // A control character in a manifest's name must not drive the terminal.
 64	        text.push_str(&format!("  {:>width$} {mark} {}\n", index + 1, name.escape_debug()));
 65	    }
 66	    eprint!("{text}");
 67	}
 68	
 69	/// One line typed at a single-line prompt; the prompt's validator asks again with the reason until [`answer`] accepts
 70	/// it, and Esc or Ctrl-C is [`CliError::Cancelled`].
 71	fn read_answer(names: &[String], marked: &[bool], one: bool) -> Result<Vec<usize>, CliError> {
 72	    let (valid_names, valid_marked) = (names.to_vec(), marked.to_vec());
 73	    let line = Text::new("Your answer")
 74	        .with_validator(move |line: &str| {
 75	            Ok(match answer(line, &valid_names, &valid_marked, one) {
 76	                Ok(_) => Validation::Valid,
 77	                Err(reason) => Validation::Invalid(reason.into()),
 78	            })
 79	        })
 80	        .prompt()?;
 81	    Ok(answer(&line, names, marked, one).expect("the validator accepted this line"))
 82	}
 83	
 84	/// The listed indices a typed line picks: the `marked` ones for an empty line (when several may be picked), else the
 85	/// ones [`choices`] names; `one` requires exactly one.
 86	fn answer(line: &str, names: &[String], marked: &[bool], one: bool) -> Result<Vec<usize>, String> {
 87	    let picked = if line.trim().is_empty() && !one {
 88	        (0..names.len())
 89	            .filter(|&index| marked.get(index) == Some(&true))
 90	            .collect()
 91	    } else {
 92	        choices(line, names)?
 93	    };
 94	    if one && picked.len() != 1 {
 95	        return Err("pick exactly one".to_owned());
 96	    }
 97	    Ok(picked)
 98	}
 99	
100	/// The listed indices an answer names, in list order. A word is a number or range counted from 1 (`3`, `1-3`) when
101	/// those rows exist, else a listed name; words are separated by spaces or commas.
102	fn choices(answer: &str, names: &[String]) -> Result<Vec<usize>, String> {
103	    let mut picked = std::collections::BTreeSet::new();
104	    for word in answer
105	        .split(|c: char| c == ',' || c.is_whitespace())
106	        .filter(|word| !word.is_empty())
107	    {
108	        let shown = word.escape_debug();
109	        let by_name = names.iter().position(|name| name == word);
110	        let indices = match (by_name, numbered(word, names.len())) {
111	            (Some(index), None | Some(Err(_))) => index..=index,
112	            (Some(index), Some(Ok(range))) if range == (index..=index) => range,
113	            (Some(_), Some(Ok(_))) => {
114	                return Err(format!("`{shown}` is both a listed name and another entry's number"))
115	            }
116	            (None, Some(range)) => range?,
117	            (None, None) => return Err(format!("`{shown}` is not a number, a range or a listed name")),
118	        };
119	        picked.extend(indices);
120	    }
121	    Ok(picked.into_iter().collect())
122	}
123	
124	/// `n` or `a-b`, counted from 1, as indices; `None` when the word is shaped like neither, `Some(Err)` when the rows are
125	/// not in the list.
126	fn numbered(word: &str, len: usize) -> Option<Result<std::ops::RangeInclusive<usize>, String>> {
127	    let (first, last) = word.split_once('-').unwrap_or((word, word));
128	    let digits = |text: &str| !text.is_empty() && text.bytes().all(|byte| byte.is_ascii_digit());
129	    if !digits(first) || !digits(last) {
130	        return None;
131	    }
132	    let listed = |text: &str| text.parse::<usize>().ok().filter(|number| (1..=len).contains(number));
133	    Some(match (listed(first), listed(last)) {
134	        (Some(low), Some(high)) if low <= high => Ok(low - 1..=high - 1),
135	        (Some(_), Some(_)) => Err(format!("`{word}` runs backwards; put the lower number first")),
136	        _ => Err(format!("`{word}` is not in the list (1-{len})")),
137	    })
138	}
139	
140	/// The editor named by `$VISUAL`, else `$EDITOR`.
141	pub struct Editor {
142	    variable: &'static str,
143	    command: String,
144	}
145	
146	/// Why the editor could not be used; its message is the warning to print.
147	#[derive(Debug, thiserror::Error)]
148	#[error("cannot use ${variable} (`{command}`): {reason}; asking for the summary here instead")]
149	pub struct EditorUnusable {
150	    variable: &'static str,
151	    command: String,
152	    reason: String,
153	}
154	
155	impl Editor {
156	    /// An empty or blank setting is unset.
157	    pub fn from_env() -> Option<Self> {
158	        ["VISUAL", "EDITOR"].into_iter().find_map(|variable| {
159	            let command = std::env::var(variable).ok()?;
160	            (!command.trim().is_empty()).then_some(Self { variable, command })
161	        })
162	    }
163	
164	    /// `VISUAL` or `EDITOR`, whichever named it.
165	    pub fn variable(&self) -> &'static str {
166	        self.variable
167	    }
168	
169	    /// Opens the editor on an empty file and returns what was saved. `None` when the editor exits non-zero (an abort,
170	    /// as `:cq` in Vim). The editor draws on stderr so stdout stays for the report.
171	    pub fn edit(self) -> Result<Option<String>, EditorUnusable> {
172	        self.try_edit().map_err(|reason| EditorUnusable {
173	            variable: self.variable,
174	            command: self.command,
175	            reason,
176	        })
177	    }
178	
179	    fn try_edit(&self) -> Result<Option<String>, String> {
180	        let words =
181	            shell_words::split(&self.command).map_err(|error| format!("it does not split into words: {error}"))?;
182	        let Some((program, args)) = words.split_first() else {
183	            return Err("it names no program".to_owned());
184	        };
185	        let failed = |error: std::io::Error| error.to_string();
186	        let file = tempfile::Builder::new()
187	            .prefix("callisto-")
188	            .suffix(".txt")
189	            .tempfile()
190	            .map_err(failed)?;
191	        let _editor_owns_ctrl_c = editor_owns_ctrl_c::enter().map_err(failed)?;
192	        let status = crate::runner::child_command(program, &[], &[])
193	            .args(args)
194	            .arg(file.path())
195	            .stdout(std::io::stderr())
196	            .status()
197	            .map_err(|error| format!("`{program}` did not start: {error}"))?;
198	        if !status.success() {
199	            return Ok(None);
200	        }
201	        let saved = std::fs::read(file.path()).map_err(failed)?;
202	        String::from_utf8(saved)
203	            .map(Some)
204	            .map_err(|error| format!("what it saved is not UTF-8 text: {}", error.utf8_error()))
205	    }
206	}
207	
208	#[cfg(unix)]
209	mod editor_owns_ctrl_c {
210	    use std::sync::atomic::{AtomicBool, Ordering};
211	    use std::sync::Arc;
212	
213	    use signal_hook::consts::SIGINT;
214	
215	    /// Ctrl-C in a line-mode editor reaches this process too: as Git's `launch_editor` does, ignore SIGINT while the
216	    /// editor runs and let its exit status decide. Dropping this gives SIGINT its default action back.
217	    pub struct Guard(Arc<AtomicBool>);
218	
219	    pub fn enter() -> std::io::Result<Guard> {
220	        let default_action = Arc::new(AtomicBool::new(false));
221	        signal_hook::flag::register_conditional_default(SIGINT, Arc::clone(&default_action))?;
222	        Ok(Guard(default_action))
223	    }
224	
225	    impl Drop for Guard {
226	        fn drop(&mut self) {
227	            self.0.store(true, Ordering::SeqCst);
228	        }
229	    }
230	}
231	
232	#[cfg(not(unix))]
233	mod editor_owns_ctrl_c {
234	    pub struct Guard;
235	
236	    pub fn enter() -> std::io::Result<Guard> {
237	        Ok(Guard)
238	    }
239	}
240	
241	#[cfg(test)]
242	mod tests {
243	    use super::{answer, choices};
244	
245	    fn names(names: &[&str]) -> Vec<String> {
246	        names.iter().map(|name| (*name).to_owned()).collect()
247	    }
248	
249	    #[test]
250	    fn an_answer_picks_by_number_range_and_name_in_list_order() {
251	        let listed = names(&["a", "b", "c", "d", "cargo/e"]);
252	        assert_eq!(choices("3, 1", &listed), Ok(vec![0, 2]));
253	        assert_eq!(choices("2-4", &listed), Ok(vec![1, 2, 3]));
254	        assert_eq!(choices("cargo/e a 1", &listed), Ok(vec![0, 4]));
255	        assert_eq!(choices("1-1,,  b", &listed), Ok(vec![0, 1]));
256	    }
257	
258	    #[test]
259	    fn an_answer_naming_nothing_listed_says_why() {
260	        let listed = names(&["a", "b", "c"]);
261	        for (answer, reason) in [
262	            ("0", "`0` is not in the list (1-3)"),
263	            ("4", "`4` is not in the list (1-3)"),
264	            ("2-9", "`2-9` is not in the list (1-3)"),
265	            ("99999999999999999999999", "is not in the list (1-3)"),
266	            ("3-1", "`3-1` runs backwards"),
267	            ("x", "`x` is not a number, a range or a listed name"),
268	            ("1-", "`1-` is not a number"),
269	            ("-1", "`-1` is not a number"),
270	            ("A", "`A` is not a number"),
271	        ] {
272	            let error = choices(answer, &listed).expect_err(answer);
273	            assert!(error.contains(reason), "{answer}: {error}");
274	        }
275	    }
276	
277	    #[test]
278	    fn a_name_that_reads_as_another_entrys_number_is_refused() {
279	        let ambiguous = "is both a listed name and another entry's number";
280	        assert!(choices("2", &names(&["2", "b"])).unwrap_err().contains(ambiguous));
281	        assert!(choices("1-2", &names(&["a", "b", "1-2"]))
282	            .unwrap_err()
283	            .contains(ambiguous));
284	        // A name that is its own number is not ambiguous.
285	        assert_eq!(choices("1", &names(&["1", "b"])), Ok(vec![0]));
286	    }
287	
288	    #[test]
289	    fn a_number_or_range_without_those_rows_is_matched_as_a_name() {
290	        assert_eq!(choices("42", &names(&["42"])), Ok(vec![0]));
291	        assert_eq!(choices("42", &names(&["a", "42"])), Ok(vec![1]));
292	        assert_eq!(choices("2-9", &names(&["a", "2-9"])), Ok(vec![1]));
293	        assert_eq!(choices("3-1", &names(&["a", "3-1"])), Ok(vec![1]));
294	        // The rows exist, so the number is a row.
295	        assert_eq!(choices("1", &names(&["42"])), Ok(vec![0]));
296	    }
297	
298	    #[test]
299	    fn an_empty_line_keeps_the_marked_ones_and_one_pick_needs_exactly_one() {
300	        let listed = names(&["a", "b", "c"]);
301	        assert_eq!(answer("  ", &listed, &[false, true, true], false), Ok(vec![1, 2]));
302	        assert_eq!(answer("", &listed, &[], false), Ok(vec![]));
303	        assert_eq!(answer("2", &listed, &[], true), Ok(vec![1]));
304	        for line in ["", "1 2", "1-2"] {
305	            assert_eq!(
306	                answer(line, &listed, &[], true),
307	                Err("pick exactly one".to_owned()),
308	                "{line:?}"
309	            );
310	        }
311	    }
312	}

