209	mod editor_owns_ctrl_c {
210	    use std::sync::atomic::{AtomicBool, Ordering};
211	    use std::sync::Arc;
212	
213	    use signal_hook::consts::SIGINT;
214	
215	    /// Ctrl-C in a line-mode editor reaches this process too: as Git's `launch_editor` does, ignore SIGINT while the
216	    /// editor runs and let its exit status decide. Dropping this gives SIGINT its default action back.
217	    pub struct Guard(Arc<AtomicBool>);
218	
219	    pub fn enter() -> std::io::Result<Guard> {
220	        let default_action = Arc::new(AtomicBool::new(false));
221	        signal_hook::flag::register_conditional_default(SIGINT, Arc::clone(&default_action))?;
222	        Ok(Guard(default_action))
223	    }
224	
225	    impl Drop for Guard {
226	        fn drop(&mut self) {
227	            self.0.store(true, Ordering::SeqCst);
228	        }
229	    }
230	}
