157	/// The wizard's questions; a scripted implementation drives tests. Esc or Ctrl-C at any of them is
158	/// [`CliError::Cancelled`].
159	trait AddPrompter {
160	    /// The indices of the packages the contributor picked; `marked` ones are picked when they just press Enter.
161	    fn pick(&mut self, heading: &str, names: &[String], marked: &[bool]) -> Result<Vec<usize>, CliError>;
162	    /// The summary; an empty answer opens `$EDITOR` for a longer one. `None` when the editor saves nothing.
163	    fn summary(&mut self, prompt: &str) -> Result<Option<Summary>, CliError>;
164	    fn confirm(&mut self, prompt: &str, default: bool) -> Result<bool, CliError>;
165	}
166	
167	struct TerminalAddPrompter {
168	    _allowed: tty::Prompts,
169	}
170	
171	impl AddPrompter for TerminalAddPrompter {
172	    fn pick(&mut self, heading: &str, names: &[String], marked: &[bool]) -> Result<Vec<usize>, CliError> {
173	        tty::pick_many(heading, names, marked)
174	    }
175	
176	    fn summary(&mut self, prompt: &str) -> Result<Option<Summary>, CliError> {
177	        let mut editor = tty::Editor::from_env();
178	        loop {
179	            let hint = match &editor {
180	                Some(editor) => format!("{prompt} (leave empty to open ${}; Esc cancels)", editor.variable()),
181	                None => format!("{prompt} (Esc cancels)"),
182	            };
183	            let opens_editor = editor.is_some();
184	            let line = Text::new(&hint)
185	                .with_validator(move |line: &str| {
186	                    Ok(match Summary::new(line) {
187	                        Err(_) if !(opens_editor && line.is_empty()) => {
188	                            Validation::Invalid("the summary cannot be blank".into())
189	                        }
190	                        _ => Validation::Valid,
191	                    })
192	                })
193	                .prompt()?;
194	            if let Ok(summary) = Summary::new(&line) {
195	                return Ok(Some(summary));
196	            }
197	            // The validator lets an empty line through only when there is an editor to open.
198	            let Some(chosen) = editor.take() else { continue };
199	            match chosen.edit() {
200	                Ok(saved) => return Ok(saved.and_then(|text| Summary::new(&text).ok())),
201	                // The answers so far are kept: the summary is asked for inline instead.
202	                Err(unusable) => prompt_line(&format!("warning: {unusable}")),
203	            }
204	        }
205	    }
206	
207	    fn confirm(&mut self, prompt: &str, default: bool) -> Result<bool, CliError> {
208	        Ok(Confirm::new(prompt).with_default(default).prompt()?)
209	    }
210	}
