212	/// A package the wizard offers, and whether it changed since its last tag.
213	struct Choice {
214	    name: String,
215	    changed: bool,
216	}
217	
218	/// The interactive wizard (as in `@changesets/cli`): packages, which are major, which of the rest are minor (the
219	/// remainder default to patch), a summary unless one was given, then a review to confirm (a dry run writes nothing, so
220	/// it does not ask). Changed packages are listed
221	/// first and marked, so Enter picks them. `None` when the contributor declines the review or the editor saves nothing, having been
222	/// told nothing was written.
223	fn run_wizard(
224	    choices: &[Choice],
225	    summary: Option<Summary>,
226	    dry_run: bool,
227	    prompter: &mut impl AddPrompter,
228	) -> Result<Option<(Vec<Entry>, Summary)>, CliError> {
229	    let answers = ask(choices, summary, dry_run, prompter)?;
230	    if answers.is_none() {
231	        prompt_line(tty::CANCELLED);
232	    }
233	    Ok(answers)
234	}
235	
236	fn ask(
237	    choices: &[Choice],
238	    summary: Option<Summary>,
239	    dry_run: bool,
240	    prompter: &mut impl AddPrompter,
241	) -> Result<Option<(Vec<Entry>, Summary)>, CliError> {
242	    if choices.is_empty() {
243	        return Err(CliError::AddNoPackagesInWorkspace);
244	    }
245	
246	    let mut ordered: Vec<&Choice> = choices.iter().collect();
247	    ordered.sort_by_key(|choice| !choice.changed);
248	    let names: Vec<String> = ordered.iter().map(|choice| choice.name.clone()).collect();
249	    let changed: Vec<bool> = ordered.iter().map(|choice| choice.changed).collect();
250	    let selected_indices = prompter.pick(
251	        "Packages in this change (* changed since its last release):",
252	        &names,
253	        &changed,
254	    )?;
255	    if selected_indices.is_empty() {
256	        return Err(CliError::AddNoPackagesSelected);
257	    }
258	    let selected_packages: Vec<String> = selected_indices.into_iter().map(|i| ordered[i].name.clone()).collect();
259	    let unmarked = vec![false; selected_packages.len()];
260	
261	    let majors = prompter.pick(
262	        "Which are a MAJOR bump? (breaking changes only)",
263	        &selected_packages,
264	        &unmarked,
265	    )?;
266	    let major_set: std::collections::HashSet<usize> = majors.into_iter().collect();
267	
268	    let minor_candidates: Vec<String> = selected_packages
269	        .iter()
270	        .enumerate()
271	        .filter(|(idx, _)| !major_set.contains(idx))
272	        .map(|(_, name)| name.clone())
273	        .collect();
274	    let minor_set: std::collections::HashSet<String> = if minor_candidates.is_empty() {
275	        std::collections::HashSet::new()
276	    } else {
277	        let minors = prompter.pick(
278	            "Which are a MINOR bump? (the rest get PATCH)",
279	            &minor_candidates,
280	            &unmarked[..minor_candidates.len()],
281	        )?;
282	        minors.into_iter().map(|idx| minor_candidates[idx].clone()).collect()
283	    };
284	
285	    let entries: Vec<Entry> = selected_packages
286	        .iter()
287	        .enumerate()
288	        .map(|(idx, name)| Entry {
289	            name: name.clone(),
290	            severity: if major_set.contains(&idx) {
291	                Severity::Major
292	            } else if minor_set.contains(name) {
293	                Severity::Minor
294	            } else {
295	                Severity::Patch
296	            },
297	        })
298	        .collect();
299	
300	    let summary = match summary {
301	        Some(summary) => summary,
302	        None => match prompter.summary("Changelog summary")? {
303	            Some(summary) => summary,
304	            None => return Ok(None),
305	        },
306	    };
307	
308	    prompt_line(&review(&entries, &summary.0));
309	    if dry_run || prompter.confirm("Write this changeset?", true)? {
310	        Ok(Some((entries, summary)))
311	    } else {
312	        Ok(None)
313	    }
314	}
