329	/// Parses a CLI-supplied severity string, reporting every value `Severity`
330	/// actually accepts (`none`, `patch`, `minor`, `major`) on failure -- not a
331	/// stale subset that omits `none`.
332	fn parse_severity(sev_str: &str) -> Result<Severity, CliError> {
333	    sev_str.parse().map_err(|_err| CliError::InvalidSeverity {
334	        value: sev_str.to_string(),
335	    })
336	}
