338	/// The wizard's packages, named by `.display_name()` so `cargo/foo` and `npm/foo` stay distinct in a polyglot workspace.
339	/// When the changed packages cannot be worked out, says so once and offers every package unpicked.
340	fn wizard_choices<'a>(
341	    packages: impl Iterator<Item = &'a callisto_model::Package>,
342	    changed: Result<std::collections::BTreeMap<callisto_model::PackageId, bool>, callisto_graph::GraphError>,
343	) -> Vec<Choice> {
344	    let changed = changed.unwrap_or_else(|error| {
345	        prompt_line(&format!(
346	            "warning: could not tell which packages changed since their last release, so none is picked: {error}"
347	        ));
348	        std::collections::BTreeMap::new()
349	    });
350	    packages
351	        .map(|pkg| Choice {
352	            name: pkg.id.display_name(),
353	            changed: changed.get(&pkg.id).copied().unwrap_or(false),
354	        })
355	        .collect()
356	}
