358	/// Writes `text` to a new file in `dir` named by `next_slug`, trying another slug whenever the name is taken, including
359	/// by a changeset another process created after this one looked. Nothing already in `dir` is ever replaced.
360	fn create_changeset(
361	    dir: &std::path::Path,
362	    archive: &std::path::Path,
363	    text: &str,
364	    permit: &ApplyPermit,
365	    mut next_slug: impl FnMut() -> String,
366	) -> Result<String, CliError> {
367	    // 8,000 possible slugs: more than a few attempts only happens when nearly all of them are taken.
368	    for _ in 0..64 {
369	        let filename = format!("{}.md", next_slug());
370	        if archived(archive, &filename)? {
371	            continue;
372	        }
373	        let path = dir.join(&filename);
374	        match callisto_model::atomic::atomic_write_new(&path, text, permit) {
375	            Ok(()) => return Ok(filename),
376	            Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {}
377	            Err(source) => {
378	                return Err(CliError::Io {
379	                    source,
380	                    path: Some(path),
381	                })
382	            }
383	        }
384	    }
385	    Err(CliError::Io {
386	        source: std::io::Error::new(
387	            std::io::ErrorKind::AlreadyExists,
388	            "no unused changeset filename found after 64 attempts",
389	        ),
390	        path: Some(dir.to_path_buf()),
391	    })
392	}
393	
394	/// Whether a Changesets v3 pre cycle archived a note under `filename`; a new note there would read as its duplicate.
395	fn archived(archive: &std::path::Path, filename: &str) -> Result<bool, CliError> {
396	    let path = archive.join(filename);
397	    callisto_model::strict_fs::exists(&path).map_err(|source| CliError::Io {
398	        source,
399	        path: Some(path),
400	    })
401	}
402	
403	/// Picks a changeset filename that does not exist yet, so a slug collision never overwrites a pending changeset.
404	fn unused_changeset_filename(dir: &std::path::Path, archive: &std::path::Path) -> Result<String, CliError> {
405	    // 8,000 possible slugs: more than a few attempts only happens when nearly all of them are taken.
406	    for _ in 0..64 {
407	        let filename = format!("{}.md", generate_human_slug());
408	        let path = dir.join(&filename);
409	        let taken = callisto_model::strict_fs::exists(&path).map_err(|source| CliError::Io {
410	            source,
411	            path: Some(path.clone()),
412	        })?;
413	        if !taken && !archived(archive, &filename)? {
414	            return Ok(filename);
415	        }
416	    }
417	    Err(CliError::Io {
418	        source: std::io::Error::new(
419	            std::io::ErrorKind::AlreadyExists,
420	            "no unused changeset filename found after 64 attempts",
421	        ),
422	        path: Some(dir.to_path_buf()),
423	    })
424	}
