142	142	/// A changeset summary: trimmed, with LF line ends, and never blank, whichever way it was supplied.
143	143	#[derive(Clone, Debug, PartialEq, Eq)]
144	144	struct Summary(String);
145	145	
146	146	impl Summary {
147	147	    /// A leading byte-order mark (some editors save one) is dropped and CRLF line ends become LF.
148	148	    fn new(text: &str) -> Result<Self, CliError> {
149	149	        let trimmed = text.trim_start_matches('\u{feff}').trim();
150	150	        if trimmed.is_empty() {
151	151	            return Err(CliError::AddSummaryEmpty);
152	152	        }
153	153	        Ok(Self(trimmed.replace("\r\n", "\n")))
154	154	    }
155	155	}
