157	157	/// The wizard's questions; a scripted implementation drives tests. Esc or Ctrl-C at any of them is
158	158	/// [`CliError::Cancelled`].
159	159	trait AddPrompter {
160	160	    /// The indices of the packages the contributor picked; `marked` ones are picked when they just press Enter.
161	161	    fn pick(&mut self, heading: &str, names: &[String], marked: &[bool]) -> Result<Vec<usize>, CliError>;
162	162	    /// The summary; an empty answer opens `$EDITOR` for a longer one. `None` when the editor saves nothing.
163	163	    fn summary(&mut self, prompt: &str) -> Result<Option<Summary>, CliError>;
164	164	    fn confirm(&mut self, prompt: &str, default: bool) -> Result<bool, CliError>;
165	165	}
