167	167	struct TerminalAddPrompter {
168	168	    _allowed: tty::Prompts,
169	169	}
170	170	
171	171	impl AddPrompter for TerminalAddPrompter {
172	172	    fn pick(&mut self, heading: &str, names: &[String], marked: &[bool]) -> Result<Vec<usize>, CliError> {
173	173	        tty::pick_many(heading, names, marked)
174	174	    }
175	175	
176	176	    fn summary(&mut self, prompt: &str) -> Result<Option<Summary>, CliError> {
177	177	        let mut editor = tty::Editor::from_env();
178	178	        loop {
179	179	            let hint = match &editor {
180	180	                Some(editor) => format!("{prompt} (leave empty to open ${}; Esc cancels)", editor.variable()),
181	181	                None => format!("{prompt} (Esc cancels)"),
182	182	            };
183	183	            let opens_editor = editor.is_some();
184	184	            let line = Text::new(&hint)
185	185	                .with_validator(move |line: &str| {
186	186	                    Ok(match Summary::new(line) {
187	187	                        Err(_) if !(opens_editor && line.is_empty()) => {
188	188	                            Validation::Invalid("the summary cannot be blank".into())
189	189	                        }
190	190	                        _ => Validation::Valid,
191	191	                    })
192	192	                })
193	193	                .prompt()?;
194	194	            if let Ok(summary) = Summary::new(&line) {
195	195	                return Ok(Some(summary));
196	196	            }
197	197	            // The validator lets an empty line through only when there is an editor to open.
198	198	            let Some(chosen) = editor.take() else { continue };
199	199	            match chosen.edit() {
200	200	                Ok(saved) => return Ok(saved.and_then(|text| Summary::new(&text).ok())),
201	201	                // The answers so far are kept: the summary is asked for inline instead.
202	202	                Err(unusable) => prompt_line(&format!("warning: {unusable}")),
203	203	            }
204	204	        }
205	205	    }
