218	218	/// The interactive wizard (as in `@changesets/cli`): packages, which are major, which of the rest are minor (the
219	219	/// remainder default to patch), a summary unless one was given, then a review to confirm (a dry run writes nothing, so
220	220	/// it does not ask). Changed packages are listed
221	221	/// first and marked, so Enter picks them. `None` when the contributor declines the review or the editor saves nothing, having been
222	222	/// told nothing was written.
223	223	fn run_wizard(
224	224	    choices: &[Choice],
225	225	    summary: Option<Summary>,
226	226	    dry_run: bool,
227	227	    prompter: &mut impl AddPrompter,
228	228	) -> Result<Option<(Vec<Entry>, Summary)>, CliError> {
229	229	    let answers = ask(choices, summary, dry_run, prompter)?;
230	230	    if answers.is_none() {
231	231	        prompt_line(tty::CANCELLED);
232	232	    }
233	233	    Ok(answers)
234	234	}
