236	236	fn ask(
237	237	    choices: &[Choice],
238	238	    summary: Option<Summary>,
239	239	    dry_run: bool,
240	240	    prompter: &mut impl AddPrompter,
241	241	) -> Result<Option<(Vec<Entry>, Summary)>, CliError> {
242	242	    if choices.is_empty() {
243	243	        return Err(CliError::AddNoPackagesInWorkspace);
244	244	    }
245	245	
246	246	    let mut ordered: Vec<&Choice> = choices.iter().collect();
247	247	    ordered.sort_by_key(|choice| !choice.changed);
248	248	    let names: Vec<String> = ordered.iter().map(|choice| choice.name.clone()).collect();
249	249	    let changed: Vec<bool> = ordered.iter().map(|choice| choice.changed).collect();
250	250	    let selected_indices = prompter.pick(
251	251	        "Packages in this change (* changed since its last release):",
252	252	        &names,
253	253	        &changed,
254	254	    )?;
255	255	    if selected_indices.is_empty() {
256	256	        return Err(CliError::AddNoPackagesSelected);
257	257	    }
258	258	    let selected_packages: Vec<String> = selected_indices.into_iter().map(|i| ordered[i].name.clone()).collect();
259	259	    let unmarked = vec![false; selected_packages.len()];
260	260	
261	261	    let majors = prompter.pick(
262	262	        "Which are a MAJOR bump? (breaking changes only)",
263	263	        &selected_packages,
264	264	        &unmarked,
265	265	    )?;
266	266	    let major_set: std::collections::HashSet<usize> = majors.into_iter().collect();
267	267	
268	268	    let minor_candidates: Vec<String> = selected_packages
269	269	        .iter()
270	270	        .enumerate()
271	271	        .filter(|(idx, _)| !major_set.contains(idx))
272	272	        .map(|(_, name)| name.clone())
273	273	        .collect();
274	274	    let minor_set: std::collections::HashSet<String> = if minor_candidates.is_empty() {
275	275	        std::collections::HashSet::new()
276	276	    } else {
277	277	        let minors = prompter.pick(
278	278	            "Which are a MINOR bump? (the rest get PATCH)",
279	279	            &minor_candidates,
280	280	            &unmarked[..minor_candidates.len()],
281	281	        )?;
282	282	        minors.into_iter().map(|idx| minor_candidates[idx].clone()).collect()
283	283	    };
284	284	
285	285	    let entries: Vec<Entry> = selected_packages
286	286	        .iter()
287	287	        .enumerate()
288	288	        .map(|(idx, name)| Entry {
289	289	            name: name.clone(),
290	290	            severity: if major_set.contains(&idx) {
291	291	                Severity::Major
292	292	            } else if minor_set.contains(name) {
293	293	                Severity::Minor
294	294	            } else {
295	295	                Severity::Patch
296	296	            },
297	297	        })
298	298	        .collect();
299	299	
300	300	    let summary = match summary {
301	301	        Some(summary) => summary,
302	302	        None => match prompter.summary("Changelog summary")? {
303	303	            Some(summary) => summary,
304	304	            None => return Ok(None),
305	305	        },
306	306	    };
307	307	
308	308	    prompt_line(&review(&entries, &summary.0));
309	309	    if dry_run || prompter.confirm("Write this changeset?", true)? {
310	310	        Ok(Some((entries, summary)))
311	311	    } else {
312	312	        Ok(None)
313	313	    }
314	314	}
