316	316	/// What the changeset will record: each package's bump, then the summary as it reaches the changelog.
317	317	fn review(entries: &[Entry], summary: &str) -> String {
318	318	    let mut text = String::from("\nThis changeset records:\n");
319	319	    for entry in entries {
320	320	        text.push_str(&format!("  {:<5}  {}\n", entry.severity.to_string(), entry.name));
321	321	    }
322	322	    text.push('\n');
323	323	    for line in summary.trim().lines() {
324	324	        text.push_str(&format!("  {line}\n"));
325	325	    }
326	326	    text
327	327	}
