358	358	/// Writes `text` to a new file in `dir` named by `next_slug`, trying another slug whenever the name is taken, including
359	359	/// by a changeset another process created after this one looked. Nothing already in `dir` is ever replaced.
360	360	fn create_changeset(
361	361	    dir: &std::path::Path,
362	362	    archive: &std::path::Path,
363	363	    text: &str,
364	364	    permit: &ApplyPermit,
365	365	    mut next_slug: impl FnMut() -> String,
366	366	) -> Result<String, CliError> {
367	367	    // 8,000 possible slugs: more than a few attempts only happens when nearly all of them are taken.
368	368	    for _ in 0..64 {
369	369	        let filename = format!("{}.md", next_slug());
370	370	        if archived(archive, &filename)? {
371	371	            continue;
372	372	        }
373	373	        let path = dir.join(&filename);
374	374	        match callisto_model::atomic::atomic_write_new(&path, text, permit) {
375	375	            Ok(()) => return Ok(filename),
376	376	            Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {}
377	377	            Err(source) => {
378	378	                return Err(CliError::Io {
379	379	                    source,
380	380	                    path: Some(path),
381	381	                })
382	382	            }
383	383	        }
384	384	    }
385	385	    Err(CliError::Io {
386	386	        source: std::io::Error::new(
387	387	            std::io::ErrorKind::AlreadyExists,
388	388	            "no unused changeset filename found after 64 attempts",
389	389	        ),
390	390	        path: Some(dir.to_path_buf()),
391	391	    })
392	392	}
393	393	
394	394	/// Whether a Changesets v3 pre cycle archived a note under `filename`; a new note there would read as its duplicate.
395	395	fn archived(archive: &std::path::Path, filename: &str) -> Result<bool, CliError> {
396	396	    let path = archive.join(filename);
397	397	    callisto_model::strict_fs::exists(&path).map_err(|source| CliError::Io {
398	398	        source,
399	399	        path: Some(path),
400	400	    })
401	401	}
402	402	
403	403	/// Picks a changeset filename that does not exist yet, so a slug collision never overwrites a pending changeset.
404	404	fn unused_changeset_filename(dir: &std::path::Path, archive: &std::path::Path) -> Result<String, CliError> {
405	405	    // 8,000 possible slugs: more than a few attempts only happens when nearly all of them are taken.
406	406	    for _ in 0..64 {
407	407	        let filename = format!("{}.md", generate_human_slug());
408	408	        let path = dir.join(&filename);
409	409	        let taken = callisto_model::strict_fs::exists(&path).map_err(|source| CliError::Io {
410	410	            source,
411	411	            path: Some(path.clone()),
412	412	        })?;
413	413	        if !taken && !archived(archive, &filename)? {
414	414	            return Ok(filename);
415	415	        }
416	416	    }
417	417	    Err(CliError::Io {
418	418	        source: std::io::Error::new(
419	419	            std::io::ErrorKind::AlreadyExists,
420	420	            "no unused changeset filename found after 64 attempts",
421	421	        ),
422	422	        path: Some(dir.to_path_buf()),
423	423	    })
424	424	}
425	425	
426	426	fn generate_human_slug() -> String {
427	427	    use std::sync::atomic::{AtomicU64, Ordering};
428	428	
429	429	    static COUNTER: AtomicU64 = AtomicU64::new(0);
430	430	
431	431	    let adjectives = [
432	432	        "swift", "clever", "bright", "silent", "brave", "calm", "eager", "gentle", "happy", "jolly", "keen", "lively",
433	433	        "mighty", "noble", "proud", "quick", "radiant", "sharp", "tough", "vivid",
434	434	    ];
435	435	    let nouns = [
436	436	        "foxes", "hawks", "wolves", "eagles", "bears", "lions", "otters", "pandas", "falcons", "tigers", "dolphins",
437	437	        "panthers", "cheetahs", "leopards", "ravens", "badgers", "lynxes", "cobras", "owls", "stags",
438	438	    ];
439	439	    let verbs = [
440	440	        "run", "fly", "leap", "soar", "dash", "hunt", "glide", "climb", "swim", "roar", "pounce", "sprint", "chase",
441	441	        "race", "bound", "drift", "jump", "strut", "spin", "surge",
442	442	    ];
443	443	
444	444	    // Each word list has 20 entries; consecutive counter values map to unique triples (a = idx % 20, n = (idx / 20) % 20,
445	445	    // v = (idx / 400) % 20), a bijection on 0..7999. A timestamp-derived offset varies the start across process restarts.
446	446	    let ts = std::time::SystemTime::now()
447	447	        .duration_since(std::time::UNIX_EPOCH)
448	448	        .map(|d| d.as_nanos() as u64)
449	449	        .unwrap_or(0);
450	450	
451	451	    let count = COUNTER.fetch_add(1, Ordering::Relaxed);
452	452	    // Shift ts right to get a slowly-varying cross-run offset (changes every ~1 µs).
453	453	    let offset = (ts >> 10) % 8000;
454	454	    let idx = (count + offset) % 8000;
455	455	
456	456	    let a = adjectives[(idx % 20) as usize];
457	457	    let n = nouns[((idx / 20) % 20) as usize];
458	458	    let v = verbs[((idx / 400) % 20) as usize];
459	459	
460	460	    format!("{a}-{n}-{v}")
461	461	}
