  1	use std::fs;
  2	use std::process::ExitCode;
  3	
  4	use callisto_graph::DependencyResolver;
  5	use callisto_model::format::{Changeset, Entry};
  6	use callisto_model::{AddReport, ApplyPermit, Severity, SCHEMA_VERSION};
  7	use inquire::validator::Validation;
  8	use inquire::{Confirm, Text};
  9	
 10	use crate::cli::{AddArgs, GlobalArgs, OutputFormat};
 11	use crate::error::CliError;
 12	use crate::output::{emit_line, emit_report, log_line, prompt_line};
 13	use crate::runner::CliCommandRunner;
 14	use crate::tty;
 15	use crate::workspace::load_workspace;
 16	
 17	pub fn handle(args: AddArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
 18	    let runner = CliCommandRunner;
 19	    let ws = load_workspace(global, &runner)?;
 20	
 21	    let mut entries = Vec::new();
 22	    // A run that cannot prompt says so before any flag is checked.
 23	    let prompts = args
 24	        .packages
 25	        .is_empty()
 26	        .then(|| {
 27	            tty::Prompts::detect(global.format).ok_or_else(|| {
 28	                let mut missing = vec!["--package"];
 29	                missing.extend(args.summary.is_none().then_some("--summary"));
 30	                CliError::NotATty { missing }
 31	            })
 32	        })
 33	        .transpose()?;
 34	    // Built before any prompt, so a blank flag fails before the review.
 35	    let mut summary = args.summary.as_deref().map(Summary::new).transpose()?;
 36	    let mut wizard = false;
 37	
 38	    if let Some(prompts) = prompts {
 39	        // The same derivation `status` reports as `changed_since_last_tag`.
 40	        let packages: Vec<&callisto_model::Package> = ws.graph.packages().collect();
 41	        let changed = ws
 42	            .tags()
 43	            .and_then(|tags| callisto_graph::changed::changed_since_last_tag(&packages, tags, ws.git_access()));
 44	        let choices = wizard_choices(packages.iter().copied(), changed);
 45	        let mut prompter = TerminalAddPrompter { _allowed: prompts };
 46	        let Some((chosen, written)) = run_wizard(&choices, summary.clone(), global.dry_run, &mut prompter)? else {
 47	            return Ok(ExitCode::SUCCESS);
 48	        };
 49	        entries = chosen;
 50	        summary = Some(written);
 51	        wizard = true;
 52	    } else {
 53	        // Non-interactive mode (flags supplied via CLI or agent)
 54	        for pkg_str in args.packages {
 55	            let (name, sev_str) = pkg_str
 56	                .rsplit_once(':')
 57	                .ok_or_else(|| CliError::AddInvalidPackageSpec { spec: pkg_str.clone() })?;
 58	
 59	            let severity = parse_severity(sev_str)?;
 60	
 61	            // Resolves by any registered native name (not just a package's
 62	            // primary/display name), reporting E102/E103 on a miss or
 63	            // ecosystem-ambiguous bare name.
 64	            callisto_graph::ConfigError::require_qualified(name, "--package")
 65	                .map_err(callisto_graph::GraphError::Config)?;
 66	            let resolved = ws.identity.resolve(name)?;
 67	
 68	            let package = resolved.display_name();
 69	            if entries.iter().any(|e: &Entry| e.name == package) {
 70	                return Err(CliError::AddDuplicatePackage {
 71	                    package: name.to_owned(),
 72	                });
 73	            }
 74	
 75	            entries.push(Entry {
 76	                // Use display_name() so "cargo/foo" is preserved, not just "foo".
 77	                // In a polyglot workspace, the bare name is ambiguous across ecosystems.
 78	                name: package,
 79	                severity,
 80	            });
 81	        }
 82	    }
 83	
 84	    let summary = summary.ok_or(CliError::AddSummaryRequired)?;
 85	    let changeset = Changeset {
 86	        entries,
 87	        summary: summary.0,
 88	    };
 89	    let text = callisto_model::format::write_changeset(&changeset)?;
 90	
 91	    let changeset_dir = ws.root.join(&ws.config.changesets_dir);
 92	    let archive_dir = ws.root.join(ws.config.pre_archive_dir());
 93	
 94	    let Some(permit) = ApplyPermit::granted_unless_dry_run(global.dry_run) else {
 95	        // Compute what WOULD be written, but never touch disk.
 96	        let filename = unused_changeset_filename(&changeset_dir, &archive_dir)?;
 97	        let rel_path = ws.config.changesets_dir.join(&filename).to_string_lossy().into_owned();
 98	        match global.format {
 99	            OutputFormat::Json => {
100	                let report = AddReport {
101	                    schema_version: SCHEMA_VERSION,
102	                    path: rel_path,
103	                    content: Some(text),
104	                    diagnostics: vec![],
105	                };
106	                emit_report(&mut std::io::stdout(), &report, true)?;
107	            }
108	            OutputFormat::Text => {
109	                emit_line(&format!(
110	                    "[DRY-RUN] Would add changeset: {rel_path} (no files written)\n\n{text}"
111	                ))?;
112	            }
113	        }
114	        return Ok(ExitCode::SUCCESS);
115	    };
116	
117	    fs::create_dir_all(&changeset_dir)?;
118	    let filename = create_changeset(&changeset_dir, &archive_dir, &text, &permit, generate_human_slug)?;
119	    let rel_path = ws.config.changesets_dir.join(&filename).to_string_lossy().into_owned();
120	
121	    match global.format {
122	        OutputFormat::Json => {
123	            let report = AddReport {
124	                schema_version: SCHEMA_VERSION,
125	                path: rel_path,
126	                content: None,
127	                diagnostics: vec![],
128	            };
129	            emit_report(&mut std::io::stdout(), &report, false)?;
130	        }
131	        OutputFormat::Text => {
132	            log_line(global.format, &format!("Added changeset: {rel_path}"))?;
133	        }
134	    }
135	    if wizard {
136	        prompt_line("Next: commit it with your change; `callisto release --dry-run` previews the release.");
137	    }
138	
139	    Ok(ExitCode::SUCCESS)
140	}
