316	/// What the changeset will record: each package's bump, then the summary as it reaches the changelog.
317	fn review(entries: &[Entry], summary: &str) -> String {
318	    let mut text = String::from("\nThis changeset records:\n");
319	    for entry in entries {
320	        text.push_str(&format!("  {:<5}  {}\n", entry.severity.to_string(), entry.name));
321	    }
322	    text.push('\n');
323	    for line in summary.trim().lines() {
324	        text.push_str(&format!("  {line}\n"));
325	    }
326	    text
327	}
328	
329	/// Parses a CLI-supplied severity string, reporting every value `Severity`
330	/// actually accepts (`none`, `patch`, `minor`, `major`) on failure -- not a
331	/// stale subset that omits `none`.
332	fn parse_severity(sev_str: &str) -> Result<Severity, CliError> {
333	    sev_str.parse().map_err(|_err| CliError::InvalidSeverity {
334	        value: sev_str.to_string(),
335	    })
336	}
337	
338	/// The wizard's packages, named by `.display_name()` so `cargo/foo` and `npm/foo` stay distinct in a polyglot workspace.
339	/// When the changed packages cannot be worked out, says so once and offers every package unpicked.
340	fn wizard_choices<'a>(
341	    packages: impl Iterator<Item = &'a callisto_model::Package>,
342	    changed: Result<std::collections::BTreeMap<callisto_model::PackageId, bool>, callisto_graph::GraphError>,
343	) -> Vec<Choice> {
344	    let changed = changed.unwrap_or_else(|error| {
345	        prompt_line(&format!(
346	            "warning: could not tell which packages changed since their last release, so none is picked: {error}"
347	        ));
348	        std::collections::BTreeMap::new()
349	    });
350	    packages
351	        .map(|pkg| Choice {
352	            name: pkg.id.display_name(),
353	            changed: changed.get(&pkg.id).copied().unwrap_or(false),
354	        })
355	        .collect()
356	}
