470	    /// Answers the wizard from a script: each package list, then the summary, then the confirmation.
471	    #[derive(Default)]
472	    struct Scripted {
473	        /// `None` answers as Esc.
474	        selections: std::collections::VecDeque<Option<Vec<usize>>>,
475	        summary: Option<Summary>,
476	        confirm: bool,
477	        /// Esc at the summary or at the confirmation.
478	        esc_at_summary: bool,
479	        esc_at_confirm: bool,
480	        confirm_asked: bool,
481	        /// The names each list was shown, in order.
482	        shown: Vec<Vec<String>>,
483	        /// Which names each list marked.
484	        marked: Vec<Vec<bool>>,
485	        summary_asked: bool,
486	    }
