488	    impl AddPrompter for Scripted {
489	        fn pick(&mut self, _heading: &str, names: &[String], marked: &[bool]) -> Result<Vec<usize>, CliError> {
490	            self.shown.push(names.to_vec());
491	            self.marked.push(marked.to_vec());
492	            self.selections
493	                .pop_front()
494	                .expect("an unexpected package list")
495	                .ok_or(CliError::Cancelled)
496	        }
497	
498	        fn summary(&mut self, _prompt: &str) -> Result<Option<Summary>, CliError> {
499	            self.summary_asked = true;
500	            if self.esc_at_summary {
501	                return Err(CliError::Cancelled);
502	            }
503	            Ok(self.summary.clone())
504	        }
505	
506	        fn confirm(&mut self, _prompt: &str, _default: bool) -> Result<bool, CliError> {
507	            self.confirm_asked = true;
508	            if self.esc_at_confirm {
509	                return Err(CliError::Cancelled);
510	            }
511	            Ok(self.confirm)
512	        }
513	    }
