1	//! `callisto add`'s wizard driven through a real pseudo-terminal: keys in, rendered output and exit status out.
2	#![cfg(unix)]
3	
4	use std::io::{Read, Write};
5	use std::os::unix::process::ExitStatusExt as _;
6	use std::path::Path;
7	use std::process::{Child, Command, ExitStatus, Stdio};
8	use std::sync::{Arc, Mutex};
9	use std::time::{Duration, Instant};
10	
11	use callisto_fixtures::git::{init_repo, run_git};
12	use rustix::pty::{grantpt, openpt, ptsname, unlockpt, OpenptFlags};
13	
14	const HIDE_CURSOR: &str = "\x1b[?25l";
15	const SHOW_CURSOR: &str = "\x1b[?25h";
16	
17	/// npm packages `a` and `b`, both released at 1.0.0, then `b` changed.
18	fn workspace() -> tempfile::TempDir {
19	    let dir = tempfile::tempdir().unwrap();
20	    let root = dir.path();
21	    init_repo(root);
22	    std::fs::write(
23	        root.join("package.json"),
24	        r#"{"name":"root","private":true,"workspaces":["packages/*"]}"#,
25	    )
26	    .unwrap();
27	    for name in ["a", "b"] {
28	        std::fs::create_dir_all(root.join(format!("packages/{name}"))).unwrap();
29	        std::fs::write(
30	            root.join(format!("packages/{name}/package.json")),
31	            format!(r#"{{"name":"{name}","version":"1.0.0"}}"#),
32	        )
33	        .unwrap();
34	    }
35	    std::fs::write(root.join("callisto.toml"), "").unwrap();
36	    run_git(root, &["add", "-A"]);
37	    run_git(root, &["commit", "-qm", "release"]);
38	    run_git(root, &["tag", "a@1.0.0"]);
39	    run_git(root, &["tag", "b@1.0.0"]);
40	    std::fs::write(root.join("packages/b/index.js"), "x").unwrap();
41	    run_git(root, &["add", "-A"]);
42	    run_git(root, &["commit", "-qm", "change b"]);
43	    dir
44	}
