46	/// `callisto add` on a pty: the child, the master side to type into, and everything it has printed so far.
47	struct Session {
48	    child: Child,
49	    master: std::fs::File,
50	    /// The child's terminal, kept open to read its settings after the child exits.
51	    tty: std::fs::File,
52	    screen: Arc<Mutex<String>>,
53	}
54	
55	impl Session {
56	    fn start(root: &Path) -> Self {
57	        Self::start_with(root, &["add"], &[])
58	    }
59	
60	    /// `callisto <args>` with `env` set; `VISUAL` and `EDITOR` are unset unless `env` names them.
61	    fn start_with(root: &Path, args: &[&str], env: &[(&str, &str)]) -> Self {
62	        Self::launch(root, args, env, true, (120, 30), true)
63	    }
64	
65	    /// `callisto <args>` with stdin and stdout on the terminal and stderr piped; read it with [`Session::stderr`].
66	    fn start_with_piped_stderr(root: &Path, args: &[&str]) -> Self {
67	        Self::launch(root, args, &[], false, (120, 30), true)
68	    }
69	
70	    fn stderr(&mut self) -> String {
71	        let mut text = String::new();
72	        self.child.stderr.take().unwrap().read_to_string(&mut text).unwrap();
73	        text
74	    }
75	
76	    /// `callisto add` on a terminal `columns` wide and `rows` high.
77	    fn start_small(root: &Path, columns: u16, rows: u16) -> Self {
78	        Self::launch(root, &["add"], &[], true, (columns, rows), true)
79	    }
80	
81	    /// `callisto add` on a terminal set up with `stty -iexten`, as some users have it.
82	    fn start_without_iexten(root: &Path) -> Self {
83	        Self::launch(root, &["add"], &[], true, (120, 30), false)
84	    }
85	
86	    fn launch(
87	        root: &Path,
88	        args: &[&str],
89	        env: &[(&str, &str)],
90	        stderr_on_terminal: bool,
91	        (columns, rows): (u16, u16),
92	        iexten: bool,
93	    ) -> Self {
94	        let master = openpt(OpenptFlags::RDWR | OpenptFlags::NOCTTY).unwrap();
95	        grantpt(&master).unwrap();
96	        unlockpt(&master).unwrap();
97	        let name = ptsname(&master, Vec::new()).unwrap();
98	        let tty = std::fs::OpenOptions::new()
99	            .read(true)
100	            .write(true)
101	            .open(name.to_str().unwrap())
102	            .unwrap();
103	        rustix::termios::tcsetwinsize(
104	            &tty,
105	            rustix::termios::Winsize {
106	                ws_row: rows,
107	                ws_col: columns,
108	                ws_xpixel: 0,
109	                ws_ypixel: 0,
110	            },
111	        )
112	        .unwrap();
113	        if !iexten {
114	            let mut mode = rustix::termios::tcgetattr(&tty).unwrap();
115	            mode.local_modes -= rustix::termios::LocalModes::IEXTEN;
116	            rustix::termios::tcsetattr(&tty, rustix::termios::OptionalActions::Now, &mode).unwrap();
117	        }
118	        let child = Command::new(env!("CARGO_BIN_EXE_callisto"))
119	            .args(["--cwd", root.to_str().unwrap()])
120	            .args(args)
121	            .env_remove("VISUAL")
122	            .env_remove("EDITOR")
123	            .env("TERM", "xterm-256color")
124	            .envs(env.iter().copied())
125	            .stdin(Stdio::from(tty.try_clone().unwrap()))
126	            .stdout(Stdio::from(tty.try_clone().unwrap()))
127	            .stderr(if stderr_on_terminal {
128	                Stdio::from(tty.try_clone().unwrap())
129	            } else {
130	                Stdio::piped()
131	            })
132	            .spawn()
133	            .unwrap();
134	        let master = std::fs::File::from(master);
135	        let screen = Arc::new(Mutex::new(String::new()));
136	        let mut reader = master.try_clone().unwrap();
137	        let sink = Arc::clone(&screen);
138	        std::thread::spawn(move || {
139	            let mut buf = [0u8; 4096];
140	            // The read fails with EIO once the child has exited and closed the terminal.
141	            while let Ok(n @ 1..) = reader.read(&mut buf) {
142	                sink.lock().unwrap().push_str(&String::from_utf8_lossy(&buf[..n]));
143	            }
144	        });
145	        Session {
146	            child,
147	            master,
148	            tty,
149	            screen,
150	        }
151	    }
152	
153	    fn screen(&self) -> String {
154	        self.screen.lock().unwrap().clone()
155	    }
156	
157	    /// Waits until the output contains `text` `times` times, then types `keys`.
158	    fn after(&mut self, text: &str, times: usize, keys: &str) {
159	        let deadline = Instant::now() + Duration::from_secs(20);
160	        while self.screen().matches(text).count() < times {
161	            assert!(Instant::now() < deadline, "never saw {text:?}:\n{}", self.screen());
162	            std::thread::sleep(Duration::from_millis(20));
163	        }
164	        // Let the prompt finish drawing and switch the terminal to raw mode before typing.
165	        std::thread::sleep(Duration::from_millis(200));
166	        self.master.write_all(keys.as_bytes()).unwrap();
167	    }
168	
169	    /// Delivers SIGINT to the child itself, as `kill -INT` or a closing terminal would, with no Ctrl-C byte typed.
170	    fn interrupt(&self) {
171	        let status = Command::new("kill")
172	            .args(["-INT", &self.child.id().to_string()])
173	            .status()
174	            .unwrap();
175	        assert!(status.success());
176	    }
177	
178	    /// The terminal is back in line mode with echo and Ctrl-C signals, as the shell expects after the child exits.
179	    fn assert_terminal_restored(&self) {
180	        let out = Command::new("stty")
181	            .arg("-a")
182	            .stdin(self.tty.try_clone().unwrap())
183	            .output()
184	            .unwrap();
185	        let settings = String::from_utf8_lossy(&out.stdout);
186	        let flags: Vec<&str> = settings.split(|c: char| c.is_whitespace() || c == ';').collect();
187	        assert!(
188	            flags.contains(&"icanon") && flags.contains(&"echo") && flags.contains(&"isig"),
189	            "the terminal is left raw:\n{settings}"
190	        );
191	    }
192	
193	    fn exit_code(&mut self) -> Option<i32> {
194	        self.status().code()
195	    }
196	
197	    fn status(&mut self) -> ExitStatus {
198	        let deadline = Instant::now() + Duration::from_secs(20);
199	        loop {
200	            if let Some(status) = self.child.try_wait().unwrap() {
201	                std::thread::sleep(Duration::from_millis(200));
202	                return status;
203	            }
204	            assert!(Instant::now() < deadline, "add did not exit:\n{}", self.screen());
205	            std::thread::sleep(Duration::from_millis(20));
206	        }
207	    }
208	}
209	
210	impl Drop for Session {
211	    /// A failed assertion must not leave the child running on its terminal.
212	    fn drop(&mut self) {
213	        // Fails only when the child has already exited, which is the goal.
214	        drop(self.child.kill());
215	        drop(self.child.wait());
216	    }
217	}
218	
219	fn changesets(root: &Path) -> Vec<String> {
220	    std::fs::read_dir(root.join(".changeset"))
221	        .map(|entries| {
222	            entries
223	                .map(|e| e.unwrap().path())
224	                .filter(|path| path.extension().is_some_and(|ext| ext == "md"))
225	                .filter(|path| path.file_name().is_some_and(|name| name != "README.md"))
226	                .map(|path| std::fs::read_to_string(path).unwrap())
227	                .collect()
228	        })
229	        .unwrap_or_default()
230	}
