233	fn the_changed_package_is_marked_so_enter_through_the_wizard_records_it() {
234	    let dir = workspace();
235	    let mut add = Session::start(dir.path());
236	    add.after("Packages in this change", 1, "\r");
237	    add.after("MAJOR", 1, "\r");
238	    add.after("MINOR", 1, "\r");
239	    add.after("Changelog summary", 1, "Fix b\r");
240	    add.after("Write this changeset?", 1, "\r");
