284	fn esc_or_ctrl_c_at_a_list_writes_nothing_and_exits_130() {
285	    // A quick double Esc is two Escape keys, not an arrow's sequence; `stty -iexten` leaves Ctrl-C a key.
286	    for (key, iexten) in [
287	        ("\x1b", true),
288	        ("\x03", true),
289	        ("1\x1b", true),
290	        ("\x1b\x1b", true),
291	        ("\x03", false),
292	        ("\x1b", false),
293	    ] {
294	        let dir = workspace();
295	        let mut add = if iexten {
296	            Session::start(dir.path())
297	        } else {
298	            Session::start_without_iexten(dir.path())
299	        };
300	        add.after("Packages in this change", 1, key);
301	        assert_eq!(add.exit_code(), Some(130), "{key:?} iexten={iexten}: {}", add.screen());
302	        let screen = add.screen();
303	        assert!(
304	            screen.contains("E343") && screen.contains("Cancelled, nothing written."),
305	            "{key:?}: {screen}"
306	        );
307	        add.assert_terminal_restored();
308	        assert!(changesets(dir.path()).is_empty());
309	    }
