635	/// The text a terminal shows, without escape sequences or line breaks, so a wrapped line reads as one.
636	fn plain(screen: &str) -> String {
637	    let mut text = String::new();
638	    let mut chars = screen.chars();
639	    while let Some(c) = chars.next() {
640	        match c {
641	            '\x1b' => {
642	                if chars.next() == Some('[') {
643	                    // A control sequence ends at its first byte in `@`..=`~`.
644	                    chars.find(|c| ('@'..='~').contains(c));
645	                }
